-- ============================================================================
-- Migration: Sheet Metal reference-data staging layer
-- Purpose: Lossless landing table for the full Sheet Metal reference dataset
--          (Variables, Wage Grade Associations, Lookup Tables, Processes,
--          Operations, Machines, Materials categories) pulled from a licensed
--          USA-region manufacturing reference tool. This is a staging/landing
--          table in the standard data-warehouse sense: it captures every
--          sourced value exactly as given, with no judgment yet about which
--          ones this app's calculators actually consume. Promotion of a
--          specific value into a real operational table (sm_lookup_*,
--          mhr_records, raw_materials, ...) happens in its own later,
--          reviewed migration that cites the source row here — never a bulk
--          "import everything as live" step. See project memory
--          project_manufacturing_intelligence_data_reconciliation.md for the
--          full rationale (this app has no progressive-die/hard-tooling
--          process coverage, so most 'variable' rows are reference-only).
-- Author: Principal Engineering Team
-- Date: 2026-08-19
-- Version: 1.0.0
-- ============================================================================

CREATE TABLE IF NOT EXISTS sm_reference_data (
    id              SERIAL PRIMARY KEY,
    category        VARCHAR(20) NOT NULL,   -- 'variable' | 'wage_grade' | 'lookup_table' | 'process' | 'operation' | 'machine' | 'material'
    source_region   VARCHAR(10) NOT NULL,   -- e.g. 'USA'
    source_version  VARCHAR(20) NOT NULL,   -- e.g. '2026-03' (dated snapshot, no vendor name)
    key             TEXT NOT NULL,          -- e.g. variable name
    value           TEXT,                   -- primary value as a string (numeric/enum/bool all stored as text)
    unit_type       TEXT,                   -- e.g. 'Length', 'Currency', 'Angle' — as given by the source
    notes           TEXT,                   -- source's own description of what the value controls
    raw             JSONB,                  -- full original row, for fidelity beyond the columns above
    imported_at     TIMESTAMPTZ DEFAULT NOW()
);

CREATE UNIQUE INDEX IF NOT EXISTS sm_reference_data_key
  ON sm_reference_data(category, source_region, source_version, key);

ALTER TABLE sm_reference_data ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Public read" ON sm_reference_data;
CREATE POLICY "Public read" ON sm_reference_data FOR SELECT USING (true);

COMMENT ON TABLE sm_reference_data IS 'Lossless staging landing zone for Sheet Metal reference data (Variables/Wage Grade/Lookup Tables/Processes/Operations/Machines/Materials), one category+region+version at a time. Not consumed directly by any calculator — see promotion migrations for what actually feeds live cost formulas.';

-- ============================================================================
-- Seed: category = 'variable' (512 rows, USA 2026-03)
-- ============================================================================
ON CONFLICT (category, source_region, source_version, key) DO NOTHING;
